def min_swaps_to_sort(arr: List[int]) -> int:
    n = len(arr)
    sorted_arr = sorted(arr)
    visit = {x: False for x in range(n)}
    swap_count = 0
    for i in range(n):
        if not visit[i] and arr[i] != sorted_arr[i]:
            cycle_count = 0
            j = i
            while not visit[j]:
                visit[j] = True
                j = arr.index(sorted_arr[j])
                cycle_count += 1
            swap_count += cycle_count - 1

    return swap_count

