def count_unique_char_permutations(s: str) -> int:
    """
    Given a string s, find the number of unique permutations of the string that can be formed
    without repeating any characters.

    Note: The result should be computed modulo 10^9 + 7.
    """
    MOD = 10**9 + 7
    fact = 1
    freq = {}
    for ch in s:
        freq[ch] = freq.get(ch, 0) + 1
    n = len(s)
    for i in range(1, n + 1):
        fact = (fact * i) % MOD
    unique_count = 1
    for k, v in freq.items():
        if v > 1:
            for j in range(2, v + 1):
                unique_count = (unique_count * j) % MOD
    return (fact * pow(unique_count, MOD - 2, MOD)) % MOD

